from engine import *
topics=[
I('format-help','Първа задача: търсим форматиране на клетка',P('В електронната таблица едно и също число може да се вижда по различен начин. <strong>Форматиране</strong> означава да настроим представянето, например брой знаци след запетаята, процент или цвят. То не е непременно промяна на самата стойност.','В първия пример от упражнението е отворена помощта на OpenOffice и е избрана тема за форматиране в Calc. Търсенето е за „формат на клетки“, а не за форматиране на текст в Writer. След намирането на темата се проследява показаната последователност.','В готовите данни клетката съдържа <strong>0,25</strong>. След избор на процентен формат се вижда <strong>25%</strong>. За намиране на командата може да се използва помощта и менюто за формат на клетки; точните надписи зависят от изданието.')+E('Проверка на резултата: 25% означава една четвърт, точно както 0,25. Не сме умножили съхранената стойност сто пъти, а сме променили начина, по който я виждаме.'),[('Приложение','Calc — електронна таблица'),('Преди','Стойност 0,25'),('След процентен формат','Виждаме 25%')],C('Кои изводи са верни?',['Търсим помощ за правилното приложение.','0,25 може да се покаже като 25%.','Форматът винаги изтрива стойността на клетката.','Помощта може да обясни конкретната команда.','Представяне и съхранена стойност са различни понятия.','За процент в клетка задължително търсим тема само за видеомонтаж.'],[0,1,3,4],'Форматът променя представянето. Подходящата помощ зависи от приложението и действието; 0,25 и 25% описват една и съща величина.')),
I('seven-zip','Запознаваме се със 7-Zip',P('Втората задача е да се намери и разгледа архиваторът <strong>7-Zip</strong>. В готовия пример е използвана официалната страница 7-zip.org, проверено е подходящото издание за компютъра и програмата е подготвена от отговорния за него човек. Тук не изпълняваме инсталация.','Прозорецът показва файлове и команди за добавяне към архив и извличане. Помощта обяснява форматите и настройките. Не е необходимо всички бутони да изглеждат като тези в Bandizip, за да разпознаем същите основни действия.','След приключване на работата в примера премахването е направено чрез командата за деинсталиране на приложение в Windows. Това е различно от затваряне на прозореца или изтриване на иконата. Задачите по-долу използват вече дадени резултати, така че не зависят от наличието на програмата.')+E('Сравняваме целите: „Добави“ създава или допълва архив; „Извличане“ връща файловете в папка; помощта обяснява настройка. Различният надпис на бутон не променя целта.'),[('Официален източник','7-zip.org'),('Общи действия','Добавяне, извличане, помощ'),('След приключване','Деинсталиране чрез предназначената команда')],C('Кои твърдения са верни?',['Използва се официалният източник и съвместимо издание.','Различни архиватори могат да извършват сходни действия.','Изтриването на икона винаги деинсталира програмата.','Помощта обяснява настройките.','Инсталирането може да изисква администратор.','Еднаквият цвят на бутоните е единственият признак за еднаква функция.'],[0,1,3,4],'Съвместимостта, източникът и предназначението на командите са важни. Интерфейсът може да се различава, а деинсталирането използва предназначена процедура.')),
I('pirin','Една папка, два архивни формата',P('В третата задача файловете за Пирин се архивират в ZIP и 7z. За да сравним честно резултатите, и в двата архива включваме <strong>едни и същи оригинални файлове</strong>. В нашия готов пример папката Pirin съдържа mapa.tif, vrah.png и tekst.txt с общ размер 20 MB.','Получени са <strong>pirin_1.zip — 12 MB</strong> и <strong>pirin_2.7z — 10 MB</strong>. При този набор вторият е с 2 MB по-малък. Това не доказва, че 7z винаги е по-малък за всеки набор и всички настройки.','Преди сравнението е проверено, че и двата архива съдържат трите файла и че при извличане се получават правилните данни. Малък файл с липсваща снимка не е добър резултат от компресия, а непълен архив.')+T(['Резултат','Файлове','Размер'],[['pirin_1.zip','Същите 3 оригинала','12 MB'],['pirin_2.7z','Същите 3 оригинала','10 MB']]),[('Изходни данни','Pirin: 3 файла, общо 20 MB'),('ZIP / 7z','12 MB / 10 MB'),('Извод за този тест','Разлика 2 MB при еднакво съдържание')],C('Кои изводи са обосновани?',['За сравнение използваме еднакво съдържание.','В примера 7z е с 2 MB по-малък.','Най-малкият архив е добър, дори да липсват нужни файлове.','Проверяваме съдържанието и извличането.','Резултатът зависи и от настройките и данните.','Един пример доказва по-малък 7z архив за всички възможни файлове.'],[0,1,3,4],'Сравнението има смисъл при еднакви оригинали и проверено съдържание. Изводът важи за дадения тест, не за всички случаи.')),
I('rila-sfx','Саморазархивиращ се пример за Рила',P('Четвъртата задача създава саморазархивиращ се пакет от папката Rila. В готовия пример в нея има rila.jpg, ezera.png и opis.txt. Резултатът е означен като <strong>rila_1.exe</strong>.','Такъв файл съдържа данните и програма за извличането им в съвместима система. В показания Windows прозорец се избира папка Rila_извлечени. След приключване там са трите очаквани файла.','Името .exe показва изпълним файл. Тук разглеждаме готовата схема, без да стартираме пакет. За действителна работа има значение довереният източник и съвместимостта, а не само името на архива. Не всяка архивираща програма предлага създаване на всички формати.')+E('Проверката е конкретна: rila.jpg, ezera.png и opis.txt са налице в отделната папка. Първоначалната Rila остава запазена. В следващото сравнение използваме същия rila_1.exe, за да няма объркване на имената.'),[('Rila','rila.jpg + ezera.png + opis.txt'),('rila_1.exe','Данни + средство за извличане'),('Rila_извлечени','Проверени са същите 3 файла')],C('Кои твърдения за примера са правилни?',['Саморазархивиращият се пакет включва средство за извличане.','В Windows примерът е .exe.','Проверяваме всички очаквани файлове.','Името .exe означава обикновен текстов документ.','Оригиналната папка може да се запази отделно.','Всеки архиватор създава всички възможни формати.'],[0,1,2,4],'SFX е изпълним пакет в показания пример. Проверените оригинали и отделният резултат позволяват ясна проверка; форматната поддръжка е различна.')),
I('remove-types','Премахваме точно избран тип файлове',P('Петата задача изисква различни промени в двата архива за Пирин. За да не загубим първото сравнение, променяме <strong>копия</strong>, а оригиналните pirin_1.zip и pirin_2.7z остават запазени.','В pirin_zip_bez_tif.zip е премахнат mapa.tif. Остават vrah.png и tekst.txt. В pirin_7z_bez_png.7z е премахнат vrah.png. Остават mapa.tif и tekst.txt. Разширението ни помага да подберем правилните файлове.','Преди потвърждението се проверява списъкът на избраните файлове. Изтриване от архива не означава, че оригиналите в папката Pirin са изтрити. След промяната отново преглеждаме съдържанието.')+T(['Копие','Премахнат файл','Остават'],[['ZIP без TIF','mapa.tif','vrah.png, tekst.txt'],['7z без PNG','vrah.png','mapa.tif, tekst.txt']])+E('Двата резултата са различни, защото условието за избор е различно. Не изтриваме автоматично една и съща снимка от двата архива.'),[('ZIP копие','Премахва се .tif'),('7z копие','Премахва се .png'),('Проверка','Във всяко копие остават 2 подходящи файла')],C('Кои твърдения отговарят на примера?',['От ZIP копието е премахнат mapa.tif.','От 7z копието е премахнат vrah.png.','tekst.txt остава и в двата резултата.','Разширението няма отношение към избора по тип файл.','Пазим първоначалните архиви отделно.','Изтриването от архив непременно премахва всички оригинали от други папки.'],[0,1,2,4],'Условието задава конкретен тип. Двете копия запазват различно съдържание, а оригиналните архиви и папката остават за проверка.')),
I('zipx','Сравняваме ZIPX и саморазархивиращ пакет',P('В шестата задача се среща още един формат: <strong>ZIPX</strong>. Той не е същото като обикновен ZIP и не всяка програма може да го създава. В готовия пример е използвана програма с подходяща поддръжка, а не предположение, че всеки архиватор има тази команда.','От същите данни за Рила са получени rila_2.zipx с размер <strong>8 MB</strong> и rila_1.exe с размер <strong>8,4 MB</strong>. В този тест ZIPX файлът е с 0,4 MB по-малък. SFX съдържа и програма за извличане, но различните настройки и методи също могат да влияят.','Сравняваме не само размер, а и възможността получателят да използва формата. Най-малкият файл не е удобен, ако няма как да бъде отворен в неговата среда.')+E('Извод за готовите данни: ZIPX спестява 0,4 MB в сравнение с дадения EXE. Преди избор проверяваме поддръжката, вместо да приемаме универсален победител.'),[('rila_2.zipx','8 MB'),('rila_1.exe','8,4 MB'),('Разлика','0,4 MB за този набор и настройки')],C('Кои изводи са правилни?',['ZIPX не се създава непременно от всеки архиватор.','В примера 8 MB е по-малко от 8,4 MB.','Проверяваме дали получателят поддържа формата.','Смяна на името от .zip на .zipx винаги преобразува данните.','SFX съдържа и програма за извличане.','Тези числа доказват еднаква разлика за всички файлове.'],[0,1,2,4],'Размерите са за конкретния пример. Съвместимостта и действителното създаване на формата имат значение; преименуването не преобразува архива.')),
I('combine','Събираме Рила и Пирин в един архив',P('Седмата задача обединява файловете от две папки в <strong>planini.zip</strong>. Добре е вътре да се запази подредбата Rila и Pirin. Така еднакви имена като opis.txt не се смесват, ако се срещат и в двете папки.','В готовия списък planini.zip съдържа две папки. Rila има три файла; Pirin също има три. При извличане в празна папка се възстановяват двете групи с общо шест файла.','Изборът на общ архив не означава, че файловете трябва да бъдат слети в един текст или че една снимка трябва да замени друга. Пакетът просто ги събира с тяхната организация.')+E('Проверка: виждат се Rila/rila.jpg, Rila/ezera.png, Rila/opis.txt, Pirin/mapa.tif, Pirin/vrah.png и Pirin/tekst.txt. Това е конкретният очакван списък за упражнението.'),[('planini.zip','Папки Rila и Pirin'),('Rila','3 файла'),('Pirin','3 файла; общо 6')],C('Кои твърдения са верни?',['В един архив може да има две папки.','Подпапките пазят организацията.','В примера общият брой е шест файла.','Двата набора задължително се превръщат в един текстов документ.','След извличане можем да проверим същата структура.','Еднакво име в различни папки непременно означава един и същ файл.'],[0,1,2,4],'Архивът събира файлове и подпапки, без да слива съдържанието им в един документ. Пътищата помагат да разграничим имената.')),
I('add-tasks','Добавяме нов набор и запазваме ново име',P('Осмата задача използва <strong>zadachi.zip</strong>. В готовия пример от него са извлечени zadacha1.txt и zadacha2.txt в отделна папка Zadachi_извлечени. Първо се проверява дали и двата файла са налице.','За да запазим planini.zip, е направено копие с ново име <strong>arhiv.zip</strong>. Към него са добавени двата извлечени файла в подпапка Zadachi. Така първоначалните шест файла и новите два образуват общо осем.','След добавянето проверяваме имената, броя и подредбата. Това е по-надеждно от преценка само по размера: архивът може да е по-голям, но пак да липсва нужен файл.')+T(['Резултат','Какво пази?'],[['planini.zip','Шестте файла за планините.'],['Zadachi_извлечени','Двата извлечени текста.'],['arhiv.zip','Шестте + двата нови файла = осем.']]),[('zadachi.zip','Извлечени 2 текста'),('Копие на planini.zip','Запазено като arhiv.zip'),('Добавяне','6 + 2 = 8 файла')],C('Кои проверки са подходящи?',['Двата текста са извлечени преди добавянето.','Първоначалният planini.zip е запазен.','arhiv.zip съдържа общо осем очаквани файла.','Само по по-големия размер знаем със сигурност, че всичко е правилно.','Проверяваме имената и подпапките.','Новото име задължително означава, че вътре няма старите файлове.'],[0,1,2,4],'Списъкът и структурата доказват какво е включено. Копието запазва предишния резултат, а размерът сам по себе си не е достатъчен.')),
I('share','Споделена папка с проверени резултати',P('Последната задача е споделена папка <strong>archiv</strong> в OneDrive. В готовата ситуация в нея са качени извлечените резултати, които групата трябва да разгледа. Използвани са ясни имена на подпапките, така че файловете за Рила, Пирин и задачите да не се смесват.','Преди споделяне е проверено съдържанието. След качването е проверено дали файловете се виждат и се отварят. Достъпът е даден за разглеждане на учебната група; ако задачата изисква съвместна промяна, разрешението за редакция трябва да се избере отделно.','Качването и споделянето са различни действия. Файл може да е в облачна папка, но още да не е достъпен за съученика. В тази мисия анализираме готовия пример, без да изискваме личен профил или публично публикуване.')+E('Готов резултат: папка archiv съдържа подредени извлечени файлове, а съученик от групата ги отваря чрез предоставения достъп. Оригиналите и всички сравнявани архиви са запазени отделно.'),[('Преди качване','Проверени имена и съдържание'),('OneDrive / archiv','Подпапки с подредени резултати'),('Споделяне','Проверен достъп на учебната група')],O('Как би описал проверения резултат от последната задача за споделяне?','Напиши 3–4 изречения със свои думи и използвай папката archiv като пример.','В папката archiv в OneDrive са качени проверени и подредени извлечени файлове. Подпапките показват кои са за Рила, Пирин и задачите. След качването е проверено дали файловете се отварят, а на учебната група е предоставен необходимият достъп за разглеждане. Самото качване не означава автоматично споделяне. За самопроверка: посочи съдържанието, подредбата и проверката на достъпа, без да твърдиш, че си използвал личен профил.'))]
build(15,'application-programs-practice','Приложни програми — упражнение','44',P('В това упражнение свързваме търсенето на помощ с работа по архиви и споделяне на резултати. Всяка от деветте задачи от учебника е представена с готови данни, действия и очакван резултат.','Ще сравняваш размери, ще проследиш добавяне и изтриване и ще разбереш защо подредбата е важна. Не е необходимо да инсталираш програми, да стартираш EXE или да влизаш в личен облачен профил.'),topics,['<strong>Търсим помощ според приложението и задачата.</strong>','<strong>Сравняваме архиви с еднакво съдържание.</strong> Резултатите важат за дадените данни и настройки.','<strong>Избираме файловете по правилния тип и пазим предишните резултати.</strong>','<strong>Проверяваме имена, брой и подпапки, а не само размер.</strong>','<strong>Качване и споделяне са различни действия.</strong> Проверяваме достъпа.'],['Деветте задачи от стр.44 са в девет последователни информационни теми.','1 помощ/Calc;2 7-Zip източник/инсталация/помощ/деинсталация;3 Pirin ZIP/7z;4 Rila SFX;5 изтриване TIF/PNG;6 ZIPX/SFX;7 planini;8 zadachi/добавяне/arhiv;9 OneDrive/archiv.'],[('7-Zip','https://www.7-zip.org/'),('OpenOffice: документация','https://www.openoffice.org/documentation/'),('WinZip: ZIPX','https://www.winzip.com/en/learn/file-formats/zipx/')], 'Уточнение: 7-Zip не създава всеки изброен формат, включително ZIPX. Условието за ZIPX е представено с подходяща програма и готови резултати. Непоследователното rila.exe/rila_1 от оригинала е уеднаквено като rila_1.exe. Архивите преди и след промяна се пазят отделно. Използваните размери са условни.')
